def solve(coins, amount):
    # Edge case: zero amount requires zero coins
    if amount == 0:
        return 0
    # Initialize DP array with amount+1 (infinity placeholder)
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    # For each sub-amount, compute minimal coins using each coin
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # If using coin c leads to a better solution, update
                candidate = dp[a - c] + 1
