def solve(n: int, b: int) -> str:
    """Convert integer n to its representation in base b (2 <= b <= 36).
    Digits are 0-9 then a-z for values 10-35. Negative numbers are prefixed with '-'.
    """
    if not (2 <= b <= 36):
        raise ValueError('Base must be between 2 and 36')
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n == 0:
        return '0'
    neg = n < 0
    n = -n if neg else n
    chars = []
    while n:
        n, rem = divmod(n, b)
        chars.append(digits[rem])
    if neg:
        chars.append('-')
    return ''.join(reversed(chars))

