def solve(matrix):
    """Return elements of a rectangular matrix in clockwise spiral order.
    Handles empty matrix and any dimensions.
    """
    if not matrix or not matrix[0]:
        return []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    res = []
    while top <= bottom and left <= right:
        # move right across top row
        for col in range(left, right + 1):
            res.append(matrix[top][col])
        top += 1
        # move down the rightmost column
        for row in range(top, bottom + 1):
            res.append(matrix[row][right])
        right -= 1
        # move left across the bottom row, if any rows remain
        if top <= bottom:
            for col in range(right, left - 1, -1):
                res.append(matrix[bottom][col])
            bottom -= 1
        # move up the leftmost column, if any columns remain
        if left <= right and top <= bottom:
            for row in range(bottom, top - 1, -1):
                res.append(matrix[row][left])
            left += 1
    return res

def solve(n):
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n-1
    limit = n
    is_prime = [True] * limit
    is_prime[0:2] = [False, False]
    import math
    for p in range(2, int(math.isqrt(limit - 1)) + 1):
        if is_prime[p]:
            step = p
            start = p * p
            is_prime[start:limit:step] = [False] * ((limit - 1 - start) // step + 1)
    return sum(is_prime)

