{"task_id": "T39", "code": "def solve(a,b):
    # DP for Levenshtein distance
    m,n = len(a), len(b)
    # If one string is empty
    if m==0:
        return n
    if n==0:
        return m
    # DP table with two rows to save space
    prev = list(range(n+1))
    for i in range(1,m+1):
        cur = [i] + [0]*n
        for j in range(1,n+1):
            if a[i-1]==b[j-1]:
                cost = 0
            else:
                cost = 1
            cur[j] = min(prev[j]+1,      # deletion
                         cur[j-1]+1,    # insertion
                         prev[j-1]+cost) # substitution
        prev = cur
    return prev[n]
