def solve(n):
    """Return the number of primes strictly less than n using the Sieve of Eratosthenes."""
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
