def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Supports +, -, *, / with integer division truncating toward zero.
    If an operation cannot be performed (e.g., insufficient operands or division by zero),
    the function returns 0.
    """
    stack = []
    for t in tokens:
        if t in '+-*/':
            if len(stack) < 2:
                return 0
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # '/'
                if b == 0:
                    return 0
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            try:
                stack.append(int(t))
            except ValueError:
                # Non-integer token, treat as 0
                stack.append(0)
    return stack[0] if len(stack) == 1 else 0

