def solve(tokens):
    """Evaluate Reverse Polish Notation with operators +, -, *, /.
    Returns integer result, truncating division toward zero.
    If the expression is invalid (e.g., insufficient operands or division by zero), returns 0.
    """
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            if len(stack) < 2:
                return 0
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                if b == 0:
                    return 0
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            try:
                stack.append(int(token))
            except Exception:
                return 0
    return stack[-1] if stack else 0

